#include "base/HabitatUtilityRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::base {
HabitatDelta HabitatUtilityRuntime::evaluate(std::span<const HabitatUtility>us,const HabitatInput&i,double dt)const{HabitatDelta o{};dt=safe::nonNegative(dt);double power=safe::nonNegative(i.powerAvailable);std::vector<HabitatUtility>v(us.begin(),us.end());std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.stableId<b.stableId;});for(const auto&u:v){if(!u.enabled)continue;double need=safe::nonNegative(u.powerDemand)*dt;if(power<need)continue;power-=need;o.powerConsumed=safe::nonNegative(o.powerConsumed+need);double r=safe::nonNegative(u.rate)*dt;switch(u.kind){case HabitatUtilityKind::AtmosphereUnit:if(i.sealed){o.pressure+=r;o.oxygen+=r*.21;}break;case HabitatUtilityKind::Scrubber:o.toxins-=r;o.smoke-=r;break;case HabitatUtilityKind::Heater:o.temperature+=r;break;case HabitatUtilityKind::Cooler:o.temperature-=r;break;case HabitatUtilityKind::WaterRecycler:o.water+=std::min(r,safe::nonNegative(i.waterAvailable));break;case HabitatUtilityKind::AirlockController:break;}}o.pressure=safe::finiteClamp(o.pressure,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.oxygen=safe::finiteClamp(o.oxygen,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.toxins=safe::finiteClamp(o.toxins,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.smoke=safe::finiteClamp(o.smoke,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.temperature=safe::finiteClamp(o.temperature,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.water=safe::finiteClamp(o.water,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);return o;}
} // namespace elysium::base
